#include <stdio.h>
#include <stdlib.h>

int magicalString(int n) {
    if (n <= 0) return 0;

    int *s = (int *)malloc((n + 2) * sizeof(int));
    if (s == NULL) return 0;

    s[0] = 1;
    s[1] = 2;
    s[2] = 2;

    int i = 2;
    int len = 3;
    int count = 1;

    while (len < n) {
        int value = (s[len - 1] == 1) ? 2 : 1;
        int times = s[i++];

        for (int j = 0; j < times && len < n; ++j) {
            s[len++] = value;
            if (value == 1) ++count;
        }
    }

    free(s);
    return count;
}

