class Solution:
    def magicalString(self, n: int) -> int:
        if n <= 0:
            return 0

        s = [1, 2, 2]
        i = 2
        count = 1

        while len(s) < n:
            value = 2 if s[-1] == 1 else 1
            times = s[i]
            i += 1

            for _ in range(times):
                if len(s) >= n:
                    break
                s.append(value)
                if value == 1:
                    count += 1

        return count

